import{_ as n,a0 as o,w as d,s as r,I as a,x as e,a1 as t,A as l,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Ubuntu 上使用 ZFS 文件系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上使用 ZFS 文件系統 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上使用 ZFS 文件系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上使用 ZFS 文件系統 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20170928 How to Use the ZFS Filesystem on Ubuntu Linux","title":"如何在 Ubuntu 上使用 ZFS 文件系統","tag":"201802","desc":""},"relativePath":"201802/20170928 How to Use the ZFS Filesystem on Ubuntu Linux.md","filePath":"[post].md"}'),h={name:"201802/20170928 How to Use the ZFS Filesystem on Ubuntu Linux.md"};function u(g,s,k,b,c,f){const i=o("Link");return d(),r("div",null,[s[16]||(s[16]=a("h1",{id:"如何在-ubuntu-上使用-zfs-文件系統",tabindex:"-1"},[e("如何在 Ubuntu 上使用 ZFS 文件系統 "),a("a",{class:"header-anchor",href:"#如何在-ubuntu-上使用-zfs-文件系統","aria-label":"Permalink to “如何在 Ubuntu 上使用 ZFS 文件系統”"},"​")],-1)),s[17]||(s[17]=a("p",null,[a("img",{src:"https://www.maketecheasier.com/assets/uploads/2017/09/zfs-feat.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在 Linux 系統上，有大量的",-1)),t(i,{href:"https://www.maketecheasier.com/best-linux-filesystem-for-ssd/"},{default:l(()=>[...s[0]||(s[0]=[e("文件系統",-1)])]),_:1}),s[2]||(s[2]=e("可以使用，那麼我們為什麼還要嘗試一個新的文件系統？它們都工作的很好，不是嗎？但是它們並不完全相同，其中的一些文件系統具有非常突出的優點，例如 ZFS。",-1))]),s[18]||(s[18]=p('<h3 id="為什麼選擇-zfs" tabindex="-1">為什麼選擇 ZFS <a class="header-anchor" href="#為什麼選擇-zfs" aria-label="Permalink to “為什麼選擇 ZFS”">​</a></h3><p>ZFS 非常的優秀。這是一個真正現代的文件系統，內置的功能對於處理大量的數據很有意義。</p><p>現在，如果您正在考慮將 ZFS 用於您的超高速 NVMe SSD，這可能不是一個最佳選擇。 它比別的文件系統要慢，不過，這完全沒有問題， 它旨在存儲大量的數據並保持安全。</p><p>ZFS 消除了建立傳統 RAID 陣列（LCTT 譯註：獨立磁盤冗餘陣列）的需要。 相反，您可以創建 ZFS 池，甚至可以隨時將驅動器添加到這些池中。 ZFS 池的行為操作與 RAID 幾乎完全相同，但功能內置於文件系統中。</p><p>ZFS 也可以替代 LVM （LCTT 譯註：邏輯盤卷管理），使您能夠動態地進行分區和管理分區，而無需處理底層的細節，也不必擔心相關的風險。</p><p>這也是一個 CoW （LCTT 譯註：寫時複製）文件系統。 這裏不會提及太多的技術性，這意味着 ZFS 可以保護您的數據免受逐漸損壞的影響。 ZFS 會創建文件的校驗和，並允許您將這些文件回滾到以前的工作版本。</p><h3 id="安裝-zfs" tabindex="-1">安裝 ZFS <a class="header-anchor" href="#安裝-zfs" aria-label="Permalink to “安裝 ZFS”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/zfs-install.jpg" alt="Install ZFS on Ubuntu" title="Install ZFS on Ubuntu"></p><p>在 Ubuntu 上安裝 ZFS 非常簡單，但對於 Ubuntu LTS （LCTT 譯註：長時間支持版本）和最新版本來説，這個過程稍有不同。</p><p><strong>Ubuntu 16.04 LTS</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install zfs</span></span></code></pre></div><p><strong>Ubuntu 17.04 及以後</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install zfsutils</span></span></code></pre></div><p>當你安裝好程序後，可以使用 ZFS 提供的工具創建 ZFS 驅動器和分區。</p><h3 id="創建池" tabindex="-1">創建池 <a class="header-anchor" href="#創建池" aria-label="Permalink to “創建池”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/zfs-create-pool.jpg" alt="Create ZFS Pool" title="Create ZFS Pool"></p><p>在 ZFS 中，池大致相當於 RAID 。 它們很靈活且易於操作。</p><h4 id="raid0" tabindex="-1">RAID0 <a class="header-anchor" href="#raid0" aria-label="Permalink to “RAID0”">​</a></h4><p>RAID0 只是把你的硬盤集中到一個池子裏面，就像一個巨大的驅動器一樣。 它可以提高你的驅動器速度，（LCTT 譯註：數據條帶化後，並行訪問，可以提高文件讀取速度）但是如果你的驅動器有損壞，你可能會失丟失數據。</p><p>要使用 ZFS 實現 RAID0，只需創建一個普通的池。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool /dev/sdc /dev/sdd</span></span></code></pre></div><h4 id="raid1-鏡像" tabindex="-1">RAID1（鏡像） <a class="header-anchor" href="#raid1-鏡像" aria-label="Permalink to “RAID1（鏡像）”">​</a></h4><p>您可以在 ZFS 中使用 <code>mirror</code> 關鍵字來實現 RAID1 功能。 RAID1 會創建一個一對一的驅動器副本。 這意味着您的數據一直在備份。 它也提高了性能。 當然，你將一半的存儲空間用於了複製。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool mirror /dev/sdc /dev/sdd</span></span></code></pre></div><h4 id="raid5-raidz1" tabindex="-1">RAID5/RAIDZ1 <a class="header-anchor" href="#raid5-raidz1" aria-label="Permalink to “RAID5/RAIDZ1”">​</a></h4><p>ZFS 將 RAID5 功能實現為 RAIDZ1。 RAID5 要求驅動器至少是 3 個。並允許您通過將備份奇偶校驗數據寫入驅動器空間的 1/n（n 是驅動器數），留下的是可用的存儲空間。 如果一個驅動器發生故障，陣列仍將保持聯機狀態，但應儘快更換髮生故障的驅動器（LCTT 譯註：與原文翻譯略有不同，原文是驅動器的數目是三的倍數，根據 wiki， RAID5 至少需要 3 塊驅動器，也可以從下面的命令中猜測)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool raidz1 /dev/sdc /dev/sdd /dev/sde</span></span></code></pre></div><h4 id="raid6-raidz2" tabindex="-1">RAID6/RAIDZ2 <a class="header-anchor" href="#raid6-raidz2" aria-label="Permalink to “RAID6/RAIDZ2”">​</a></h4><p>RAID6 與 RAID5 幾乎完全相同，但它至少需要四個驅動器。 它將奇偶校驗數據加倍，最多允許兩個驅動器損壞，而不會導致陣列關閉（LCTT 譯註：這裏也與原文略有出入，原文是驅動器的數目是四的倍數，根據 wiki ，RAID6 至少需要四個驅動器)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool raidz2 /dev/sdc /dev/sdd /dev/sde /dev/sdf</span></span></code></pre></div><h4 id="raid10-條帶化鏡像" tabindex="-1">RAID10（條帶化鏡像） <a class="header-anchor" href="#raid10-條帶化鏡像" aria-label="Permalink to “RAID10（條帶化鏡像）”">​</a></h4><p>RAID10 旨在通過數據條帶化提高存取速度和數據冗餘來成為一個兩全其美的解決方案。 你至少需要四個驅動器，但只能使用一半的空間。 您可以通過在同一個池中創建兩個鏡像來創建 RAID10 中的池（LCTT 譯註：這裏也與原文略有出入，原文是驅動器的數目是四的倍數，根據 wiki， RAID10 至少需要四個驅動器）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool mirror /dev/sdc /dev/sdd mirror /dev/sde /dev/sdf</span></span></code></pre></div><h3 id="池的操作" tabindex="-1">池的操作 <a class="header-anchor" href="#池的操作" aria-label="Permalink to “池的操作”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/zfs-pool-status.jpg" alt="ZFS pool Status" title="ZFS pool Status"></p><p>還有一些管理工具，一旦你創建了你的池，你就必須使用它們來操作。 首先，檢查你的池的狀態。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool status</span></span></code></pre></div><h4 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to “更新”">​</a></h4><p>當你更新 ZFS 時，你也需要更新你的池。 當您檢查它們的狀態時，您的池會通知您任何更新。 要更新池，請運行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool upgrade your-pool</span></span></code></pre></div><p>你也可以更新全部池。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool upgrade -a</span></span></code></pre></div><h4 id="添加驅動器" tabindex="-1">添加驅動器 <a class="header-anchor" href="#添加驅動器" aria-label="Permalink to “添加驅動器”">​</a></h4><p>您也可以隨時將驅動器添加到池中。 告訴 <code>zpool</code> 池的名稱和驅動器的位置，它會處理好一切。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool add your-pool /dev/sdx</span></span></code></pre></div><h3 id="其它的一些想法" tabindex="-1">其它的一些想法 <a class="header-anchor" href="#其它的一些想法" aria-label="Permalink to “其它的一些想法”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/zfs-pool-open.jpg" alt="ZFS in File Browser" title="ZFS in File Browser"></p><p>ZFS 會在您的池的根文件系統中創建一個目錄。 您可以使用 GUI 文件管理器或 CLI 按名稱瀏覽它們。</p><p>ZFS 非常強大，還有很多其它的東西可以用它來做，但這些都是基礎。 這是一個優秀的存儲負載文件系統，即使它只是一個用於文件的硬盤驅動器的 RAID 陣列。 ZFS 在 NAS 系統上也非常出色。</p><p>無論 ZFS 的穩定性和可靠性如何，在您的硬盤上實施新的功能時，最好備份您的數據。</p><hr>',51)),a("p",null,[s[4]||(s[4]=e("via: ",-1)),t(i,{href:"https://www.maketecheasier.com/use-zfs-filesystem-ubuntu-linux/"},{default:l(()=>[...s[3]||(s[3]=[e("https://www.maketecheasier.com/use-zfs-filesystem-ubuntu-linux/",-1)])]),_:1})]),a("p",null,[s[8]||(s[8]=e("作者：",-1)),t(i,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:l(()=>[...s[5]||(s[5]=[e("Nick Congleton",-1)])]),_:1}),s[9]||(s[9]=e(" 譯者：",-1)),t(i,{href:"https://github.com/amwps290"},{default:l(()=>[...s[6]||(s[6]=[e("amwps290",-1)])]),_:1}),s[10]||(s[10]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[11]||(s[11]=[e("LCTT",-1)])]),_:1}),s[14]||(s[14]=e(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:l(()=>[...s[12]||(s[12]=[e("Linux中國",-1)])]),_:1}),s[15]||(s[15]=e(" 榮譽推出",-1))])])}const F=n(h,[["render",u]]);export{C as __pageData,F as default};
